mapper.select:
select feedback_id, user_id, content, reply, solve,
       send_datetime, reply_datetime, solve_datetime
from t_feedback user_id=#{userId}

   and solve=#{solve}

ORDER BY send_datetime desc

select a.feedback_id, a.user_id, b.username, a.content, a.reply, a.solve, a.send_datetime, a.reply_datetime, a.solve_datetime from t_feedback a left join t_user b on a.user_id=b.user_id
a.solve=#{type}
ORDER BY a.send_datetime desc
